members.doc:
`rules` is each rule's name and what it holds, in the order they are
documented:

- `decl`, a name declared once, a newtype's field without `!`;
- `scope`, every variable bound;
- `tyscope`, every type variable bound, none with the name of a type
  constructor, and none that a lambda binds bound already;
- `tycon`, every type constructor declared or built in;
- `kind`, every type of the kind its place wants;
- `eval`, `!` only at a binder, a parameter, a field or a component of
  an unboxed tuple, of a lifted type;
- `instantiate`, a type argument a lifted type without `!`, of its
  variable's kind;
- `app`, a function applied to types and values its type takes;
- `force`, an atom given where an evaluated value is wanted evaluated;
- `lit`, a literal in its type's range;
- `lambda`, a lambda that binds something, each name once;
- `let`, a `let` of a lifted type, bound to an expression of it;
- `case`, alternatives of the scrutinee's type, that cover it and agree;
- `con`, a constructor of a data type, given its types and fields;
- `prim`, a primitive of CorePrim, saturated;
- `cast`, a cast into or out of a newtype at its head;
- `val`, a value of the top level of its type;
- `main`, `main` of type `World -> (utuple World T)`.

members.spec:
val unit : {fault : fault option, imports : (string * abi) list, makesShared : bool, newtypes : (string * bool) list}
           * Core.program
           -> {text : string, names : (string * string) list, abi : (string * abi) list, boxed : (string * bool) list}

type interface = {core : Core.program, primTypes : (string * string) list, builtinCons : (string * string) list,
                  fields : (string * string list) list, constructors : (string * string list) list,
                  leaves : string list, defaults : string list, forced : (string * bool list) list}

datatype dict =
    DParam of string
  | DInst of {inst : string, tys : HsTypes.ty list, args : dict list}
  | DSuper of {dict : dict, cls : string, super : string}

datatype record =
    Use of {tys : HsTypes.ty list, dicts : dict list}
  | Overloaded of {ty : HsTypes.ty, dicts : (string * dict) list}
  | Binding of {scheme : scheme, params : string list}
  | Mono of HsTypes.ty
  | Instance of {inst : string, vars : string list, params : string list, supers : dict list}
  | Class of {param : string}
  | Defaulted of {var : string, preds : HsTypes.pred list, candidates : HsTypes.ty list, module_ : string,
                  choice : HsTypes.ty}

val check : {env : env, unit : module_ list, cycleDefault : cycleDefault,
             prelude : string * string -> string option, fixity : string -> (HsAst.fixity * int) option,
             evidence : HsEvidence.table}
            -> {env : env, errors : (HsSource.span * string) list, derived : (string * string * HsAst.decl list) list}

val check : {groups : module list list, main : string option, cycleDefault : bool,
             records : {table : HsEvidence.table, env : HsInfer.env,
                        derived : (string * string * HsAst.decl list) list} option,
             claims : claims option, where_ : HsSource.span -> string, fault : string, library : library option}
            -> {report : report, target : target, part : library}

datatype meta =
    Free of {id : int, level : int, home : string}
  | Link of ty

datatype read =
    Name of {within : string, space : string, qual : string, name : string}
  | Item of {from : string, space : string, name : string}
  | Exports of string
  | Instance of {cls : string, tycon : string}
  | Standard of {space : string, name : string}
  | Entity of string
